(** StepRefine.v: generated by scripts/generate_step_refine.py.
    Single-cycle retirement refinement of the actual step rule against
    [kami_step], one theorem per opcode at its canonical encoding. *)
Require Import Kami.Kami Kami.Semantics Kami.Lib.NatLib.
From Coq Require Import String NArith Arith Lia FunctionalExtensionality.
From KamiHW Require Import ThieleTypes HWBoundary RuleNext RuleStep BoundaryDecoded StepEval
  StepWordFacts StepFields StepRefineCommon PopcountSWAR ImplementationContract Abstraction.
Require Import Kernel.VMState Kernel.VMStep.
Import VMStep.VMStep.
Open Scope string_scope.

Ltac snap_projections :=
  cbn [snap_pc snap_mu snap_err snap_halted snap_regs snap_mem snap_partition_ops
    snap_mdl_ops snap_info_gain snap_error_code snap_mu_tensor snap_pt_sizes
    snap_pt_next_id snap_certified snap_wc_same_00 snap_wc_diff_00 snap_wc_same_01
    snap_wc_diff_01 snap_wc_same_10 snap_wc_diff_10 snap_wc_same_11 snap_wc_diff_11
    snap_module_tensors snap_rich_state snap_csr_cert_addr snap_csr_status snap_csr_err
    snap_csr_heap_base snap_logic_acc snap_mstatus hwb_snapshot].

Ltac syntactic := lazymatch goal with |- ?x = ?x => reflexivity end.

(** pc + 1 and mu + cost under no-wrap premises in context. *)
Ltac close_pc :=
  lazymatch goal with
  | H : wordToNat (hw_pc ?b) + 1 < pow2 WordSz
    |- wordToNat (wplus (hw_pc ?b) (natToWord _ 1)) = S (wordToNat (hw_pc ?b)) =>
      rewrite wordToNat_wplus_bounded; rewrite wordToNat_word1_32; [lia|exact H]
  end.

Ltac close_mu_cost :=
  lazymatch goal with
  | H : wordToNat (hw_mu ?b) + wordToNat ?c < pow2 WordSz
    |- wordToNat (wplus (hw_mu ?b) (zext ?c 24)) = wordToNat (hw_mu ?b) + wordToNat ?c =>
      rewrite wordToNat_wplus_bounded; rewrite wordToNat_zext8_32; [reflexivity|exact H]
  end.

(** mu + cost + 1 (cert-setter charge) under a no-wrap premise. *)
Ltac close_mu_cost_one :=
  lazymatch goal with
  | H : wordToNat (hw_mu ?b) + wordToNat ?c + 1 < pow2 WordSz
    |- wordToNat (wplus (wplus (hw_mu ?b) (zext ?c 24)) (natToWord _ 1)) = _ =>
      assert (H1 : wordToNat (wplus (hw_mu b) (zext c 24)) = wordToNat (hw_mu b) + wordToNat c)
        by (rewrite wordToNat_wplus_bounded; rewrite ?wordToNat_zext8_32; [reflexivity|lia]);
      rewrite wordToNat_wplus_one_bounded by (rewrite H1; exact H);
      rewrite H1; lia
  end.

(** mu + bits + cost + 1 (bit-priced charge) under a no-wrap premise. *)
Ltac close_mu_bits :=
  lazymatch goal with
  | H : wordToNat (hw_mu ?b) + wordToNat ?bw + wordToNat ?c + 1 < pow2 WordSz
    |- wordToNat (wplus (wplus (wplus (hw_mu ?b) (zext ?bw 24)) (zext ?c 24)) (natToWord _ 1)) = _ =>
      assert (H1 : wordToNat (wplus (hw_mu b) (zext bw 24)) = wordToNat (hw_mu b) + wordToNat bw)
        by (rewrite wordToNat_wplus_bounded; rewrite ?wordToNat_zext8_32; [reflexivity|lia]);
      assert (H2 : wordToNat (wplus (wplus (hw_mu b) (zext bw 24)) (zext c 24)) =
                   wordToNat (hw_mu b) + wordToNat bw + wordToNat c)
        by (rewrite wordToNat_wplus_bounded; rewrite ?H1, ?wordToNat_zext8_32; [reflexivity|lia]);
      rewrite wordToNat_wplus_one_bounded by (rewrite H2; exact H);
      rewrite H2; lia
  end.

(** Data-memory update at a truncated address: [pre] normalizes the address,
    [tac] proves the written value. *)
Ltac close_mem_update pre tac :=
  refine (eq_trans (hwb_vector_nat_update _ _ _ _ _) _);
  let j := fresh "j" in
  extensionality j;
  change RegCount with (2 ^ RegIdxSz); change MEM_SIZE with 128;
  rewrite ?hwb_vector_nat_at_mod;
  unfold MemAddrSz, RegIdxSz;
  rewrite wordToNat_trunc7; pre;
  lazymatch goal with
  | |- (if Nat.eqb ?i ?d then _ else _) = _ => destruct (Nat.eqb i d); [tac|reflexivity]
  end.

(** Register-file update: reduce to the written value, then [tac] proves it. *)
Ltac close_vector_update tac :=
  refine (eq_trans (hwb_vector_nat_update _ _ _ _ _) _);
  let j := fresh "j" in
  extensionality j;
  change RegCount with (2 ^ RegIdxSz);
  rewrite ?hwb_vector_nat_at_mod;
  repeat match goal with
  | |- context [wordToNat ?d mod 2 ^ RegIdxSz] =>
      rewrite (Nat.mod_small (wordToNat d) (2 ^ RegIdxSz)) by apply wordToNat_lt_pow2_small
  end;
  unfold RegIdxSz;
  lazymatch goal with
  | |- (if Nat.eqb ?i ?d then _ else _) = _ => destruct (Nat.eqb i d); [tac|reflexivity]
  end.

Theorem step_add_refines : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 (b : HWB) ,
  step_fetched b = add_word a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 ->
  hwb_bianchi b = false -> hw_err b = false -> hw_halted b = false ->
  wordToNat (hw_pc b) + 1 < pow2 WordSz ->
  wordToNat (hw_mu b) + wordToNat (bits8 c0 c1 c2 c3 c4 c5 c6 c7) < pow2 WordSz ->
  wordToNat (hw_regs b (bits4 b4 b5 b6 b7)) + wordToNat (hw_regs b (bits4 b0 b1 b2 b3)) < pow2 WordSz ->
  hwb_snapshot (step_next b) = kami_step (hwb_snapshot b) (instr_add (wordToNat (bits4 a0 a1 a2 a3)) (wordToNat (bits4 b4 b5 b6 b7)) (wordToNat (bits4 b0 b1 b2 b3)) (wordToNat (bits8 c0 c1 c2 c3 c4 c5 c6 c7))).
Proof.
  intros a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b  Hf Hb Herr Hhalt Hpc Hmu Hv.
  unfold hwb_snapshot at 1.
  rewrite (step_rich_frame b (step_add_morph_valid_table a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb) (step_add_morph_src_table a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb) (step_add_morph_dst_table a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb) (step_add_morph_coupling_desc_table a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb) (step_add_morph_identity_table a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb) (step_add_morph_next_id a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb) (step_add_coupling_desc_label_table a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb) (step_add_coupling_desc_label_len_table a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb)).
  rewrite (step_add_pc a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_mu a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_err a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_halted a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_regs a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_mem a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_error_code a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_cert_addr a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_partition_ops a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_mdl_ops a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_info_gain a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_mu_tensor a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_module_tensors a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_ptTable a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_pt_next_id a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_certified a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_wc_same_00 a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_wc_diff_00 a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_wc_same_01 a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_wc_diff_01 a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_wc_same_10 a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_wc_diff_10 a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_wc_same_11 a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb), (step_add_wc_diff_11 a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb).
  rewrite step_keeps_csr_status, step_keeps_csr_heap_base, step_keeps_logic_acc, step_keeps_mstatus.
  unfold kami_step, kami_write_reg, kami_write_mem, kami_advance_default, kami_advance_info.
  snap_projections. rewrite ?Herr, ?Hhalt.
  all: apply kami_snapshot_ext; snap_projections.
  all: first [ syntactic | close_pc | close_mu_cost | close_vector_update ltac:(rewrite wordToNat_wplus_bounded by exact Hv; rewrite word64_below_pow2_32 by exact Hv; reflexivity) ].
Qed.

