  rewrite step_keeps_csr_status, step_keeps_csr_heap_base, step_keeps_logic_acc, step_keeps_mstatus.
  unfold kami_step, kami_write_reg, kami_write_mem, kami_advance_default, kami_advance_info.
  snap_projections. rewrite ?Herr, ?Hhalt.
  all: apply kami_snapshot_ext; snap_projections.
  all: first [ syntactic | close_pc | close_mu_cost | close_vector_update ltac:(rewrite wordToNat_wminus_le by exact Hv; rewrite word64_sub_small by (exact Hv || apply wordToNat_bound); rewrite word64_below_pow2_32 by apply word32_sub_lt_pow2_32; reflexivity) ].
Qed.

Theorem step_and_refines : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 (b : HWB) ,
  step_fetched b = and_word a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 ->
  hwb_bianchi b = false -> hw_err b = false -> hw_halted b = false ->
  wordToNat (hw_pc b) + 1 < pow2 WordSz ->
  wordToNat (hw_mu b) + wordToNat (bits8 c0 c1 c2 c3 c4 c5 c6 c7) < pow2 WordSz ->
  hwb_snapshot (step_next b) = kami_step (hwb_snapshot b) (instr_and (wordToNat (bits4 a0 a1 a2 a3)) (wordToNat (bits4 b4 b5 b6 b7)) (wordToNat (bits4 b0 b1 b2 b3)) (wordToNat (bits8 c0 c1 c2 c3 c4 c5 c6 c7))).
Proof.
  intros a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b  Hf Hb Herr Hhalt Hpc Hmu.
